update public.article_cache set translation = '{"texts": ["Something special happened at the Sariska Tiger Reserve in India. A tiger hunted a leopard. Tigers and leopards are both members of the large cat family. Usually tigers are larger and stronger. However, it''s not common for them to live in the same area. The Sariska Tiger Reserve is a famous place in India. Many wild animals live there. It''s a special park created to protect tigers. This kind of event doesn''t happen often. It''s an interesting incident that shows the lives of animals in the wild. You can feel the power of nature.", "Korean Teacher Shortage Becomes Serious, School Classes Disrupted", "What is an \"anxiety bag\"? A Popular Trend", "The United States and China Resume Talks Over Trade Issues", "\"Talking Pig\" Becomes SNS Star", "Apple Greatly Improves iPhone Speed with New AI Chip"], "sentences": [{"text": "인도의 사리스카 호랑이 보호구역에서 특별한 일이 일어났어요.", "translation": "Something special happened at the Sariska tiger reserve in India.", "vocab": [{"ko": "보호구역", "en": "reserve; protected area"}, {"ko": "특별하다", "en": "to be special"}, {"ko": "일어나다", "en": "to happen; to occur"}], "analysis": [{"type": "grammar", "label": "~에서", "exp": "Location particle indicating where an action takes place.", "example_in_sentence": "보호구역에서"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense ending for completed action. 일어나다 (to happen) → 일어났어요 (happened).", "example_in_sentence": "일어났어요"}]}, {"text": "호랑이 한 마리가 표범을 사냥했어요.", "translation": "A tiger hunted a leopard.", "vocab": [{"ko": "호랑이", "en": "tiger"}, {"ko": "표범", "en": "leopard"}, {"ko": "사냥하다", "en": "to hunt"}], "analysis": [{"type": "grammar", "label": "~을/를", "exp": "Accusative particle marking direct object. 표범 (leopard) is the target of hunting.", "example_in_sentence": "표범을"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense ending. 사냥하다 (to hunt) → 사냥했어요 (hunted).", "example_in_sentence": "사냥했어요"}]}, {"text": "호랑이와 표범은 모두 큰 고양이과 동물이에요.", "translation": "Tigers and leopards are both large felines.", "vocab": [{"ko": "고양이과", "en": "felidae; feline family"}, {"ko": "동물", "en": "animal"}], "analysis": [{"type": "grammar", "label": "~와/과", "exp": "Conjunctive particle joining nouns. 호랑이 (tiger) + 표범 (leopard).", "example_in_sentence": "호랑이와 표범은"}, {"type": "grammar", "label": "~이에요", "exp": "Copula for present tense affirmative statement. Links subject to predicate noun.", "example_in_sentence": "동물이에요"}]}, {"text": "보통 호랑이가 더 크고 강해요.", "translation": "Usually tigers are larger and stronger.", "vocab": [{"ko": "보통", "en": "usually; normally"}, {"ko": "크다", "en": "to be big; to be large"}, {"ko": "강하다", "en": "to be strong"}], "analysis": [{"type": "grammar", "label": "~고", "exp": "Connective ending joining two adjectives or actions. 크다 (big) + 강하다 (strong).", "example_in_sentence": "더 크고 강해요"}, {"type": "grammar", "label": "~아/어요", "exp": "Present tense ending. 크다 → 커요; 강하다 → 강해요.", "example_in_sentence": "강해요"}]}, {"text": "하지만 같은 지역에서 사는 경우는 많지 않아요.", "translation": "However, cases where they live in the same area are not common.", "vocab": [{"ko": "하지만", "en": "but; however"}, {"ko": "지역", "en": "area; region"}, {"ko": "경우", "en": "case; instance"}], "analysis": [{"type": "grammar", "label": "~는", "exp": "Topic particle. 경우는 (the case).", "example_in_sentence": "경우는"}, {"type": "grammar", "label": "~지 않다", "exp": "Negation pattern. 많다 (to be many) → 많지 않다 (not many).", "example_in_sentence": "많지 않아요"}]}, {"text": "사리스카 호랑이 보호구역은 인도에서 유명한 곳이에요.", "translation": "The Sariska tiger reserve is a famous place in India.", "vocab": [{"ko": "유명하다", "en": "to be famous"}, {"ko": "곳", "en": "place; location"}], "analysis": [{"type": "grammar", "label": "~에서", "exp": "Location particle indicating where something is situated or known.", "example_in_sentence": "인도에서"}, {"type": "grammar", "label": "~은/는", "exp": "Topic particle marking the subject. 보호구역은 (the reserve).", "example_in_sentence": "보호구역은"}]}, {"text": "많은 야생 동물들이 살고 있어요.", "translation": "Many wild animals live there.", "vocab": [{"ko": "많다", "en": "to be many; to be a lot"}, {"ko": "야생", "en": "wild"}, {"ko": "살다", "en": "to live; to inhabit"}], "analysis": [{"type": "grammar", "label": "~고 있다", "exp": "Progressive aspect indicating ongoing action. 살다 (to live) → 살고 있어요 (are living).", "example_in_sentence": "살고 있어요"}]}, {"text": "호랑이를 보호하기 위해 만든 특별한 공원이에요.", "translation": "It is a special park made to protect tigers.", "vocab": [{"ko": "보호하다", "en": "to protect"}, {"ko": "만들다", "en": "to make; to create"}, {"ko": "공원", "en": "park"}], "analysis": [{"type": "grammar", "label": "~기 위해", "exp": "Purpose connector. ~기 (nominalizer) + 위해 (for the sake of). Indicates the purpose of an action.", "example_in_sentence": "보호하기 위해"}, {"type": "grammar", "label": "~(으)ㄴ (past verb modifier)", "exp": "Describes a noun with a completed action. 만들다 drops ㄹ: 만들다 → 만든 공원 (a park that was made).", "example_in_sentence": "만든"}]}, {"text": "이런 일은 자주 일어나지 않아요.", "translation": "Such things do not happen often.", "vocab": [{"ko": "이런", "en": "such; this kind of"}, {"ko": "자주", "en": "often; frequently"}], "analysis": [{"type": "grammar", "label": "~지 않다", "exp": "Negation pattern. 일어나다 (to happen) → 일어나지 않아요 (does not happen).", "example_in_sentence": "일어나지 않아요"}, {"type": "grammar", "label": "~은/는", "exp": "Topic particle. 일은 (the matter).", "example_in_sentence": "일은"}]}, {"text": "야생에서 동물들의 생활을 보여주는 흥미로운 사건이에요.", "translation": "It is an interesting event showing the life of animals in the wild.", "vocab": [{"ko": "야생", "en": "wild; wilderness"}, {"ko": "생활", "en": "life; living"}, {"ko": "보여주다", "en": "to show"}, {"ko": "흥미롭다", "en": "to be interesting"}], "analysis": [{"type": "grammar", "label": "~는 (verb modifier)", "exp": "Describes a noun with a present action. 보여주다 (to show) → 보여주는 사건 (an event that shows).", "example_in_sentence": "보여주는"}, {"type": "grammar", "label": "~의", "exp": "Possessive particle. 동물들의 (of the animals) indicates ownership/relationship.", "example_in_sentence": "동물들의"}]}, {"text": "자연의 힘을 느낄 수 있어요.", "translation": "We can feel the power of nature.", "vocab": [{"ko": "자연", "en": "nature"}, {"ko": "힘", "en": "power; strength"}, {"ko": "느끼다", "en": "to feel; to sense"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 수 있다", "exp": "Expresses ability or possibility: ''can''. 느끼다 (to feel) → 느낄 수 있어요 (can feel).", "example_in_sentence": "느낄 수 있어요"}, {"type": "grammar", "label": "~의", "exp": "Possessive particle. 자연의 (of nature) indicates the source of power.", "example_in_sentence": "자연의 힘을"}]}], "version": "s6"}', vocab = '[{"ko": "보호구역", "en": "reserve; protected area", "note": ""}, {"ko": "특별하다", "en": "to be special", "note": ""}, {"ko": "일어나다", "en": "to happen; to occur", "note": ""}, {"ko": "호랑이", "en": "tiger", "note": ""}, {"ko": "표범", "en": "leopard", "note": ""}, {"ko": "사냥하다", "en": "to hunt", "note": ""}, {"ko": "고양이과", "en": "felidae; feline family", "note": ""}, {"ko": "동물", "en": "animal", "note": ""}, {"ko": "보통", "en": "usually; normally", "note": ""}, {"ko": "크다", "en": "to be big; to be large", "note": ""}, {"ko": "강하다", "en": "to be strong", "note": ""}, {"ko": "하지만", "en": "but; however", "note": ""}, {"ko": "지역", "en": "area; region", "note": ""}, {"ko": "경우", "en": "case; instance", "note": ""}, {"ko": "유명하다", "en": "to be famous", "note": ""}, {"ko": "곳", "en": "place; location", "note": ""}, {"ko": "많다", "en": "to be many; to be a lot", "note": ""}, {"ko": "야생", "en": "wild", "note": ""}, {"ko": "살다", "en": "to live; to inhabit", "note": ""}, {"ko": "보호하다", "en": "to protect", "note": ""}, {"ko": "만들다", "en": "to make; to create", "note": ""}, {"ko": "공원", "en": "park", "note": ""}, {"ko": "이런", "en": "such; this kind of", "note": ""}, {"ko": "자주", "en": "often; frequently", "note": ""}, {"ko": "생활", "en": "life; living", "note": ""}, {"ko": "보여주다", "en": "to show", "note": ""}, {"ko": "흥미롭다", "en": "to be interesting", "note": ""}, {"ko