appen.", "ex_ko": "앞으로 더 많은 나라에서 비슷한 서비스를 도입할 것 같아요.", "ex_en": "It seems like more countries will introduce similar services in the future."}]}', updated_at = now() where article_id = 'mopuqlei3erj' and md5(translation) = '7b43222f9c93906f241b29f93d0aa474';
update public.article_cache set translation = '{"sentences": [{"text": "인도 하이데라바드에서 우버(Uber) 택시를 탄 사람이 재미있는 안내문을 발견했어요.", "idx": 0, "translation": "A person who took an Uber taxi in Hyderabad, India discovered an interesting notice.", "vocab": [{"ko": "하이데라바드", "en": "Hyderabad", "note": "city in India"}, {"ko": "안내문", "en": "notice, guide text", "note": "written information or instructions"}, {"ko": "발견하다", "en": "to discover, find", "note": "~했어요 = discovered (past)"}], "grammar": [{"pattern": "~ㄴ 사람", "exp": "A person who performed an action (relative clause with past modifier).", "example_in_sentence": "우버 택시를 탄 사람"}, {"pattern": "~았/었어요", "exp": "Past tense polite ending indicating a completed action.", "example_in_sentence": "발견했어요"}], "analysis": []}, {"text": "이 안내문은 인터넷에서 화제가 되었어요.", "idx": 1, "translation": "This notice became a topic on the internet.", "vocab": [{"ko": "안내문", "en": "notice, guide text"}, {"ko": "인터넷", "en": "internet"}, {"ko": "화제", "en": "topic, subject of discussion"}], "grammar": [{"pattern": "~가 되다", "exp": "To become; expressing a change of state.", "example_in_sentence": "화제가 되었어요"}, {"pattern": "~았/었어요", "exp": "Past tense polite ending.", "example_in_sentence": "되었어요"}], "analysis": []}, {"text": "우버는 스마트폰으로 택시를 부르는 서비스예요.", "idx": 2, "translation": "Uber is a service for calling a taxi with a smartphone.", "vocab": [{"ko": "우버", "en": "Uber (proper noun)"}, {"ko": "스마트폰", "en": "smartphone"}, {"ko": "부르다", "en": "to call, summon"}], "grammar": [{"pattern": "~(으)로 ~하는 서비스", "exp": "A service (noun) that does an action using a means or tool.", "example_in_sentence": "스마트폰으로 택시를 부르는 서비스"}], "analysis": []}, {"text": "전 세계 많은 나라에서 사용하고 있어요.", "idx": 3, "translation": "Many countries around the world are using it.", "vocab": [{"ko": "전 세계", "en": "whole world, worldwide"}, {"ko": "나라", "en": "country, nation"}, {"ko": "사용하다", "en": "to use"}], "grammar": [{"pattern": "~고 있다", "exp": "Continuous action; something is being done or is in progress.", "example_in_sentence": "사용하고 있어요"}], "analysis": []}, {"text": "한국에서도 우버와 비슷한 서비스들이 있어요.", "idx": 4, "translation": "In Korea, too, there are services similar to Uber.", "vocab": [{"ko": "한국", "en": "Korea"}, {"ko": "비슷하다", "en": "to be similar, alike"}, {"ko": "서비스", "en": "service"}], "grammar": [{"pattern": "~ㄴ/은 (adjective modifier)", "exp": "Using an adjective to modify a noun; adjective in relative clause form.", "example_in_sentence": "비슷한 서비스들"}], "analysis": []}, {"text": "인도의 택시 기사들은 손님들에게 친근하게 다가가려고 노력해요.", "idx": 5, "translation": "Taxi drivers in India try to approach passengers in a friendly manner.", "vocab": [{"ko": "인도", "en": "India"}, {"ko": "택시 기사", "en": "taxi driver"}, {"ko": "손님", "en": "passenger, customer"}, {"ko": "친근하다", "en": "to be friendly, approachable"}], "grammar": [{"pattern": "~게 다가가다", "exp": "To approach in a certain manner; adverbial form ~게 modifies the verb.", "example_in_sentence": "친근하게 다가가려고"}, {"pattern": "~려고 노력하다", "exp": "To try to; expressing intention and effort.", "example_in_sentence": "다가가려고 노력해요"}], "analysis": []}, {"text": "재미있는 안내문을 붙여서 손님들이 즐겁게 여행할 수 있게 해요.", "idx": 6, "translation": "By putting up fun notices, they help passengers enjoy their trip.", "vocab": [{"ko": "재미있다", "en": "to be fun, interesting"}, {"ko": "붙이다", "en": "to attach, post, stick"}, {"ko": "즐겁다", "en": "to be joyful, happy"}, {"ko": "여행", "en": "trip, travel"}], "grammar": [{"pattern": "~아/어 주다", "exp": "To do something for/to someone as a favor or benefit.", "example_in_sentence": "즐겁게 여행할 수 있게 해요"}, {"pattern": "~을/를 수 있다", "exp": "Ability; to be able to do something.", "example_in_sentence": "여행할 수 있게"}], "analysis": []}, {"text": "이런 작은 배려가 여행을 더 특별하게 만들어요.", "idx": 7, "translation": "Such small consideration makes travel more special.", "vocab": [{"ko": "작다", "en": "to be small, little"}, {"ko": "배려", "en": "consideration, thoughtfulness"}, {"ko": "특별하다", "en": "to be special, particular"}], "grammar": [{"pattern": "~ㄴ/은 것", "exp": "Nominalizer; turning an adjective into a noun.", "example_in_sentence": "작은 배려"}, {"pattern": "~게 만들다", "exp": "To make/cause something to become a certain state; causative.", "example_in_sentence": "특별하게 만들어요"}], "analysis": []}, {"text": "다른 나라의 문화를 경험할 수 있는 좋은 기회가 되기도 해요.", "idx": 8, "translation": "It also becomes a good opportunity to experience the culture of other countries.", "vocab": [{"ko": "다른", "en": "other, different"}, {"ko": "나라", "en": "country"}, {"ko": "문화", "en": "culture"}, {"ko": "경험하다", "en": "to experience"}], "grammar": [{"pattern": "~ㄹ 수 있는", "exp": "Able to; potential form used as a relative clause modifier.", "example_in_sentence": "경험할 수 있는"}, {"pattern": "~기도 하다", "exp": "Also; expresses an additional possibility or occurrence.", "example_in_sentence": "되기도 해요"}], "analysis": []}], "version": "p2"}', vocab = '[{"ko": "하이데라바드", "en": "Hyderabad", "note": "city in India"}, {"ko": "안내문", "en": "notice, guide text", "note": "written information or instructions"}, {"ko": "발견하다", "en": "to discover, find", "note": "~했어요 = discovered (past)"}, {"ko": "인터넷", "en": "internet", "note": ""}, {"ko": "화제", "en": "topic, subject of discussion", "note": ""}, {"ko": "우버", "en": "Uber (proper noun)", "note": ""}, {"ko": "스마트폰", "en": "smartphone", "note": ""}, {"ko": "부르다", "en": "to call, summon", "note": ""}, {"ko": "전 세계", "en": "whole world, worldwide", "note": ""}, {"ko": "나라", "en": "country, nation", "note": ""}, {"ko": "사용하다", "en": "to use", "note": ""}, {"ko": "한국", "en": "Korea", "note": ""}, {"ko": "비슷하다", "en": "to be similar, alike", "note": ""}, {"ko": "서비스", "en": "service", "note": ""}, {"ko": "인도", "en": "India", "note": ""}, {"ko": "택시 기사", "en": "taxi driver", "note": ""}, {"ko": "손님", "en": "passenger, customer", "note": ""}, {"ko": "친근하다", "en": "to be friendly, approachable", "note": ""}, {"ko": "재미있다", "en": "to be fun, interesting", "note": ""}, {"ko": "붙이다", "en": "to attach, post, stick", "note": ""}, {"ko": "즐겁다", "en": "to be joyful, happy", "note": ""}, {"ko": "여행", "en": "trip, travel", "note": ""}, {"ko": "작다", "en": "to be small, little", "note": ""}, {"ko": "배려", "en": "consideration, thoughtfulness", "note": ""}, {"ko": "특별하다", "en": "to be special, particular", "note": ""}, {"ko": "다른", "en": "other, different", "note": ""}, {"ko": "문화", "en": "culture", "note": ""}, {"ko": "경험하다", "en": "to experience", "note": ""}, {"word": "화제가 되다", "reading": "hwaje-ga doe-da", "meaning": "to become a topic of conversation; to become talked about", "context": "이 안내문은 인터넷에서 화제가 되었어요"}, {"word": "기사", "reading": "gi-sa", "meaning": "driver; taxi driver", "context": "인도의 택시 기사들은 손님들에게"}, {"word": "다가가다", "reading": "da-ga-ga-da", "meaning": "to approach; to come close to", "context": "손님들에게 친근하게 다가가려고"}, {"word": "기회", "reading": "gi-hoe", "meaning": "opportunity; chance", "context": "좋은 기회가 되기도 해요"}]', grammar = '{"patterns": []}', updated_at = now() where article_id = 'mopur6a3o877' and md5(translation) = 'bd6ab27407acbd1ec7985486ca4af9d9';
update public.article_cache set translation = '{"sentences": [{"text": "미국의 뱅크 오브 아메리카(Bank of America) ATM에 특별한 경고 메시지가 나타났어요.", "idx": 0, "translation": "A special warning message appeared on Bank of America ATMs in the United States.", "vocab": [{"ko": "경고 메시지", "en": "warning message", "note": "메시지 = message (loanword)"}, {"ko": "나타나다", "en": "to appear, to show up", "note": "past tense: 나타났어요"}], "grammar": [{"pattern": "~에 ~이 나타났다", "exp": "A warning message appeared on the ATM.", "example_in_sentence": "ATM에 특별한 경고 메시지가 나타났어요"}], "analysis": []}, {"text": "이 경고문이 인터넷에서 화제가 되고 있어요.", "idx": 1, "translation": "This warning message is becoming a hot topic on the internet.", "vocab": [{"ko": "경고문", "en": "warning text/notice", "note": "문 = text, writing"}, {"ko": "화제가 되다", "en": "to become a topic of discussion", "note": "화제 = topic"}], "grammar": [{"pattern": "~이/가 화제가 되다", "exp": "Something becomes a hot topic.", "example_in_sentence": "경고문이 인터넷에서 화제가 되고 있어요"}], "analysis": []}, {"text": "보통 ATM에는 \"돈을 조심하세요\" 같은 일반적인 경고가 있어요.", "idx": 2, "translation": "Usually ATMs have general warnings like ''Be careful with your money.''", "vocab": [{"ko": "보통", "en": "usually, ordinarily", "note": "보통 = general/normal"}, {"ko": "일반적", "en": "general; typical", "note": "일반 = general"}], "grammar": [], "analysis": []}, {"text": "하지만 이번 경고문은 조금 달랐어요.", "idx": 3, "translation": "However, this warning message was a little different.", "vocab": [{"ko": "하지만", "en": "but, however", "note": "conjunction"}, {"ko": "조금", "en": "a little, slightly", "note": "정도 can also be used"}], "grammar": [], "analysis": []}, {"text": "많은 사람들이 이 ATM 경고문을 보고 재미있다고 생각했어요.", "idx": 4, "translation": "Many people saw this ATM warning message and thought it was funny.", "vocab": [{"ko": "재미있다", "en": "to be funny, interesting", "note": "opposite: 재미없다"}], "grammar": [{"pattern": "~고 ~다", "exp": "Two consecutive actions or states (and).", "example_in_sentence": "보고 재미있다고 생각했어요"}], "analysis": []}, {"text": "그래서 온라인 커뮤니티에 사진을 올렸어요.", "idx": 5, "translation": "So they uploaded photos to online communities.", "vocab": [{"ko": "올리다", "en": "to upload, to post", "note": "올렸어요 = uploaded (past)"}, {"ko": "커뮤니티", "en": "community", "note": "loanword"}], "grammar": [{"pattern": "~어서 ~다", "exp": "Reason/cause: because of this, so...", "example_in_sentence": "그래서 온라인 커뮤니티에 사진을 올렸어요"}], "analysis": []}, {"text": "한국의 ATM도 가끔 재미있는 메시지가 나와요.", "idx": 6, "translation": "Korean ATMs also sometimes have funny messages.", "vocab": [{"ko": "가끔", "en": "sometimes, occasionally", "note": "~곤 하다 also means sometimes"}], "grammar": [], "analysis": []}, {"text": "이런 작은 것들이 사람들에게 즐거움을 줄 수 있어요.", "idx": 7, "translation": "These small things can bring joy to people.", "vocab": [{"ko": "즐거움", "en": "joy, happiness, pleasure", "note": "즐거우면 = if joyful; 즐기다 = to enjoy"}, {"ko": "주다", "en": "to give", "note": "줄 수 있다 = can give"}], "grammar": [{"pattern": "~ㄹ 수 있다", "exp": "Can do / is possible to do.", "example_in_sentence": "즐거움을 줄 수 있어요"}], "analysis": []}]}', vocab = '[{"ko": "경고 메시지", "en": "warning message", "note": "메시지 = message (loanword)"}, {"ko": "나타나다", "en": "to appear, to show up", "note": "past tense: 나타났어요"}, {"ko": "경고문", "en": "warning text/notice", "note": "문 = text, writing"}, {"ko": "화제가 되다", "en": "to become a topic of discussion", "note": "화제 = topic"}, {"ko": "보통", "en": "usually, ordinarily", "note": "보통 = general/normal"}, {"ko": "일반적", "en": "general; typical", "note": "일반 = general"}, {"ko": "하지만", "en": "but, however", "note": "conjunction"}, {"ko": "조금", "en": "a little, slightly", "note": "정도 can also be used"}, {"ko": "재미있다", "en": "to be funny, interesting", "note": "opposite: 재미없다"}, {"ko": "올리다", "en": "to upload, to post", "note": "올렸어요 = uploaded (past)"}, {"ko": "커뮤니티", "en": "community", "note": "loanword"}, {"ko": "가끔", "en": "sometimes, occasionally", "note": "~곤 하다 also means sometimes"}, {"ko": "즐거움", "en": "joy, happiness, pleasure", "note": "즐거우면 = if joyful; 즐기다 = to enjoy"}, {"ko": "주다", "en": "to give", "note": "줄 수 있다 = can give"}, {"word": "화제", "reading": "hwa-je", "meaning": "topic; subject of discussion", "context": "이 경고문이 인터넷에서 화제가 되고 있어요"}, {"word": "메시지", "reading": "me-si-ji", "meaning": "message", "context": "특별한 경고 메시지가 나타났어요"}]', grammar = '{"patterns": []}', updated_at = now() where article_id = 'mopurql4wvl1' and md5(translation) = 'a76af9977ccb198069c7ab2765c8cc13';
update public.article_cache set translation = '{"texts": ["A child sex offender living in Thailand concealed his identity using a special method. He used photo manipulation software to make his face unrecognizable.", "In 2007, the international police organization Interpol reverse-traced this technology. They restored the manipulated photos to their original state and identified the perpetrator''s face. As a result, they were able to arrest the criminal.", "The perpetrator was released from prison in 2017. He is currently known to be living in Canada.", "This case demonstrates how digital technology is applied to criminal investigations. Even though criminals misuse technology, police forensic science continues to advance further."], "sentences": [{"text": "태국에 살던 아동 성범죄자가 특별한 방법으로 자신의 신원을 숨겼어요.", "translation": "A child sex offender who was living in Thailand hid his identity using a special method.", "vocab": [{"ko": "성범죄자", "en": "sex offender"}, {"ko": "신원", "en": "identity"}, {"ko": "숨기다", "en": "to hide; to conceal"}], "analysis": [{"type": "grammar", "label": "~던 (past progressive/habitual modifier)", "exp": "Modifies a noun to indicate a past habitual or ongoing state. Attaches to verb stem: 살다 → 살던.", "example_in_sentence": "살던"}]}, {"text": "그는 사진 변조 프로그램을 이용해서 얼굴을 알아볼 수 없게 만들었습니다.", "translation": "He used a photo-manipulation program to make his face unrecognizable.", "vocab": [{"ko": "변조", "en": "alteration; manipulation"}, {"ko": "이용하다", "en": "to use; to utilize"}, {"ko": "알아보다", "en": "to recognize; to identify"}], "analysis": [{"type": "grammar", "label": "~아/어서 (connective: reason/means)", "exp": "Connects two clauses indicating cause, reason, or sequence of actions. Here, shows means: 이용하다 → 이용해서.", "example_in_sentence": "이용해서"}, {"type": "grammar", "label": "~ㄹ 수 없다 (cannot; unable to)", "exp": "Negation of possibility. Attaches to verb stem: 알아보다 → 알아볼 수 없다.", "example_in_sentence": "알아볼 수 없게"}, {"type": "grammar", "label": "~게 만들다", "exp": "Makes something end up in a certain state. 알아볼 수 없다 → 알아볼 수 없게 만들다 = to make it impossible to recognize.", "example_in_sentence": "없게 만들었습니다"}]}, {"text": "2007년 국제경찰기구 인터폴(Interpol)이 이 기술을 역추적했어요.", "translation": "In 2007, Interpol, the international police organization, traced back this technology.", "vocab": [{"ko": "국제경찰기구", "en": "international police organization"}, {"ko": "역추적", "en": "reverse tracing; backtracking"}], "analysis": []}, {"text": "변조된 사진을 원래대로 복원해서 범인의 얼굴을 확인했습니다.", "translation": "They restored the altered photo to its original state and confirmed the offender''s face.", "vocab": [{"ko": "복원하다", "en": "to restore; to recover"}, {"ko": "범인", "en": "offender; criminal"}, {"ko": "확인하다", "en": "to confirm; to verify"}], "analysis": [{"type": "grammar", "label": "~아/어서 (connective: sequential action)", "exp": "Connects two consecutive actions. Here shows sequential progression: 복원하다 → 복원해서.", "example_in_sentence": "복원해서"}]}, {"text": "그 결과 범인을 체포할 수 있었어요.", "translation": "As a result, they were able to arrest the offender.", "vocab": [{"ko": "결과", "en": "result; outcome"}, {"ko": "체포하다", "en": "to arrest; to apprehend"}], "analysis": [{"type": "grammar", "label": "~ㄹ 수 있다 (can; able to)", "exp": "Expresses ability or possibility. Attaches to verb stem: 체포하다 → 체포할 수.", "example_in_sentence": "체포할 수 있었어요"}]}, {"text": "범인은 2017년에 감옥에서 풀려났어요.", "translation": "The offender was released from prison in 2017.", "vocab": [{"ko": "감옥", "en": "prison; jail"}, {"ko": "풀려나다", "en": "to be released; to be set free"}], "analysis": []}, {"text": "현재는 캐나다에서 살고 있다고 알려졌습니다.", "translation": "Currently, it is known that he is living in Canada.", "vocab": [{"ko": "현재", "en": "present; currently"}, {"ko": "알려지다", "en": "to be known; to become known"}], "analysis": [{"type": "grammar", "label": "~고 있다 (progressive aspect)", "exp": "Indicates an ongoing action or state. Verb stem + 고 있다: 살다 → 살고 있다.", "example_in_sentence": "살고 있다"}, {"type": "grammar", "label": "~다고 알려지다", "exp": "Reports what is known: ''it is known that ~''. 살고 있다 → 살고 있다고 알려졌습니다 = it is known that he is living.", "example_in_sentence": "살고 있다고 알려졌습니다"}]}, {"text": "이 사건은 디지털 기술이 범죄 수사에 어떻게 활용되는지 보여주는 사례예요.", "translation": "This case demonstrates how digital technology is utilized in criminal investigation.", "vocab": [{"ko": "활용되다", "en": "to be utilized; to be put to use"}, {"ko": "수사", "en": "investigation; inquiry"}, {"ko": "사례", "en": "case; example; instance"}], "analysis": [{"type": "grammar", "label": "~는지 (indirect question)", "exp": "Turns a question into part of the sentence. 어떻게 활용되다 → 어떻게 활용되는지 = how it is used.", "example_in_sentence": "어떻게 활용되는지"}, {"type": "grammar", "label": "~는 (present participle modifier)", "exp": "Modifies a noun to show present tense or habitual action. 보여주다 → 보여주는.", "example_in_sentence": "보여주는"}]}, {"text": "범죄자들이 기술을 악용해도 경찰의 과학 수사 기술이 더 발전하고 있습니다.", "translation": "Even though criminals abuse technology, police forensic technology is advancing further.", "vocab": [{"ko": "악용하다", "en": "to abuse; to misuse"}, {"ko": "발전하다", "en": "to develop; to advance; to progress"}], "analysis": [{"type": "grammar", "label": "~아/어도 (even if; even though)", "exp": "Concessive connective showing contrast or exception. 악용하다 → 악용해도.", "example_in_sentence": "악용해도"}, {"type": "grammar", "label": "~고 있다 (progressive aspect)", "exp": "Indicates ongoing or habitual action in present. 발전하다 → 발전하고 있다.", "example_in_sentence": "발전하고 있습니다"}]}], "version": "s6"}', vocab = '[{"ko": "성범죄자", "en": "sex offender", "note": ""}, {"ko": "신원", "en": "identity", "note": ""}, {"ko": "숨기다", "en": "to hide; to conceal", "note": ""}, {"ko": "변조", "en": "alteration; manipulation", "note": ""}, {"ko": "이용하다", "en": "to use; to utilize", "note": ""}, {"ko": "알아보다", "en": "to recognize; to identify", "note": ""}, {"ko": "국제경찰기구", "en": "international police organization", "note": ""}, {"ko": "역추적", "en": "reverse tracing; backtracking", "note": ""}, {"ko": "복원하다", "en": "to restore; to recover", "note": ""}, {"ko": "범인", "en": "offender; criminal", "note": ""}, {"ko": "확인하다", "en": "to confirm; to verify", "note": ""}, {"ko": "결과", "en": "result; outcome", "note": ""}, {"ko": "체포하다", "en": "to arrest; to apprehend", "note": ""}, {"ko": "감옥", "en": "prison; jail", "note": ""}, {"ko": "풀려나다", "en": "to be released; to be set free", "note": ""}, {"ko": "현재", "en": "present; currently", "note": ""}, {"ko": "알려지다", "en": "to be known; to become known", "note": ""}, {"ko": "활용되다", "en": "to be utilized; to be put to use", "note": ""}, {"ko": "수사", "en": "investigation; inquiry", "note": ""}, {"ko": "사례", "en": "case; example; instance", "note": ""}, {"ko": "악용하다", "en": "to abuse; to misuse", "note": ""}, {"ko": "발전하다", "en": "to develop; to advance; to progress", "note": ""}]', grammar = '{"patterns": [{"name": "~던 (past progressive/habitual modifier)", "level": "Intermediate", "exp": "Modifies a noun to indicate a past habitual or ongoing state. Attaches to verb stem: 살다 → 살던.", "ex_ko": "태국에 살던 아동 성범죄자가 특별한 방법으로 자신의 신원을 숨겼어요.", "ex_en": "A child sex offender who was living in Thailand hid his identity using a special method."}, {"name": "~아/어서 (connective: sequential action)", "level": "Intermediate", "exp": "Connects two clauses indicating cause, reason, or sequence of actions. Here, shows means: 이용하다 → 이용해서.", "ex_ko": "그는 사진 변조 프로그램을 이용해서 얼굴을 알아볼 수 없게 만들었습니다.", "ex_en": "He used a photo-manipulation program to make his face unrecognizable."}, {"name": "~ㄹ 수 없다 (cannot; unable to)", "level": "Intermediate", "exp": "Negation of possibility. Attaches to verb stem: 알아보다 → 알아볼 수 없다.", "ex_ko": "그는 사진 변조 프로그램을 이용해서 얼굴을 알아볼 수 없게 만들었습니다.", "ex_en": "He used a photo-manipulation program to make his face unrecognizable."}, {"name": "~게 만들다", "level": "Intermediate", "exp": "Makes something end up in a certain state. 알아볼 수 없다 → 알아볼 수 없게 만들다 = to make it impossible to recognize.", "ex_ko": "그는 사진 변조 프로그램을 이용해서 얼굴을 알아볼 수 없게 만들었습니다.", "ex_en": "He used a photo-manipulation program to make his face unrecognizable."}, {"name": "~ㄹ 수 있다 (can; able to)", "level": "Intermediate", "exp": "Expresses ability or possibility. Attaches to verb stem: 체포하다 → 체포할 수.", "ex_ko": "그 결과 범인을 체포할 수 있었어요.", "ex_en": "As a result, they were able to arrest the offender."}, {"name": "~고 있다 (progressive aspect)", "level": "Intermediate", "exp": "Indicates an ongoing action or state. Verb stem + 고 있다: 살다 → 살고 있다.", "ex_ko": "현재는 캐나다에서 살고 있다고 알려졌습니다.", "ex_en": "Currently, it is known that he is living in Canada."}, {"name": "~다고 알려지다", "level": "Intermediate", "exp": "Reports what is known: ''it is known that ~''. 살고 있다 → 살고 있다고 알려졌습니다 = it is known that he is living.", "ex_ko": "현재는 캐나다에서 살고 있다고 알려졌습니다.", "ex_en": "Currently, it is known that he is living in Canada."}, {"name": "~는지 (indirect question)", "level": "Intermediate", "exp": "Turns a question into part of the sentence. 어떻게 활용되다 → 어떻게 활용되는지 = how it is used.", "ex_ko": "이 사건은 디지털 기술이 범죄 수사에 어떻게 활용되는지 보여주는 사례예요.", "ex_en": "This case demonstrates how digital technology is utilized in criminal investigation."}, {"name": "~는 (present participle modifier)", "level": "Intermediate", "exp": "Modifies a noun to show present tense or habitual action. 보여주다 → 보여주는.", "ex_ko": "이 사건은 디지털 기술이 범죄 수사에 어떻게 활용되는지 보여주는 사례예요.", "ex_en": "This case demonstrates how digital technology is utilized in criminal investigation."}, {"name": "~아/어도 (even if; even though)", "level": "Intermediate", "exp": "Concessive connective showing contrast or exception. 악용하다 → 악용해도.", "ex_ko": "범죄자들이 기술을 악용해도 경찰의 과학 수사 기술이 더 발전하고 있습니다.", "ex_en": "Even though criminals abuse technology, police forensic technology is advancing further."}]}', updated_at = now() where article_id = 'moqeemxnb1db' and md5(translation) = '301c4ef3637ab9e1bed80d59e06979cb';
update public.article_cache set translation = '{"texts": ["A Soviet-Indian friendship propaganda poster created in the 1950s is becoming a hot topic online. The poster contains the message \"Soviets and Indians are brothers.\"", "This poster is a historical document that demonstrates the special relationship the Soviet Union and India had during the Cold War. At that time, the Soviet Union pursued a policy that emphasized friendly relations with Asian countries.", "The 1950s was a period right after the Korean War ended, when the world was divided into two camps. This is an interesting historical document that offers a glimpse into the Soviet Union''s diplomatic policy toward India during these circumstances.", "This poster is currently receiving considerable attention from overseas online communities. It is valued as precious historical evidence that helps us understand international relations and propaganda culture during the Cold War era."], "sentences": [{"text": "1950년대에 만들어진 소련-인도 우정 선전 포스터가 온라인에서 화제가 되고 있어요.", "translation": "A Soviet-Indian friendship propaganda poster created in the 1950s is becoming a topic of discussion online.", "vocab": [{"ko": "만들어지다", "en": "to be made; to be created"}, {"ko": "선전", "en": "propaganda; promotion"}, {"ko": "화제가 되다", "en": "to become a topic; to attract attention"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (past modifier)", "exp": "Past modifier on a passive verb. 만들어지다 → 만들어진 포스터 = a poster that was made.", "example_in_sentence": "만들어진"}, {"type": "grammar", "label": "~고 있어요 (progressive aspect)", "exp": "Indicates an ongoing action in present tense; ~고 있다 in polite form emphasizes continuity.", "example_in_sentence": "화제가 되고 있어요"}]}, {"text": "포스터에는 ''소련인과 인도인은 형제다''라는 메시지가 담겨 있습니다.", "translation": "The poster contains a message saying ''Soviets and Indians are brothers.''", "vocab": [{"ko": "담기다", "en": "to be contained; to be embedded"}, {"ko": "메시지", "en": "message"}], "analysis": [{"type": "grammar", "label": "~(이)라는 (quoting modifier)", "exp": "Quotes content to describe the noun after it. ''...형제다''라는 메시지 = a message saying ''...are brothers''.", "example_in_sentence": "''소련인과 인도인은 형제다''라는 메시지"}, {"type": "grammar", "label": "~어 있다 (resultative state)", "exp": "Indicates a state resulting from a completed action; 담기다 → 담겨 있다.", "example_in_sentence": "담겨 있습니다"}]}, {"text": "이 포스터는 냉전 시대에 소련과 인도가 맺었던 특별한 관계를 보여주는 역사적 자료예요.", "translation": "This poster is a historical material that shows the special relationship that the Soviet Union and India formed during the Cold War era.", "vocab": [{"ko": "냉전", "en": "Cold War"}, {"ko": "맺다", "en": "to form; to establish"}, {"ko": "자료", "en": "material; data; resource"}], "analysis": [{"type": "grammar", "label": "~었던 (past tense participle with experiential nuance)", "exp": "Modifies noun to indicate past completed action; 맺다 → 맺었던. Often used to reference historical or past experience.", "example_in_sentence": "맺었던 특별한 관계"}, {"type": "grammar", "label": "~는 (present participle modifier)", "exp": "Modifies noun; 보여주다 → 보여주는 indicates an action defining the noun.", "example_in_sentence": "보여주는 역사적 자료"}]}, {"text": "당시 소련은 아시아 국가들과의 우호 관계를 강조하는 정책을 펼쳤습니다.", "translation": "At that time, the Soviet Union pursued a policy that emphasized friendly relations with Asian countries.", "vocab": [{"ko": "당시", "en": "at that time; then"}, {"ko": "우호", "en": "friendship; friendliness"}, {"ko": "강조하다", "en": "to emphasize; to stress"}, {"ko": "펼치다", "en": "to unfold; to carry out; to pursue"}], "analysis": [{"type": "grammar", "label": "~는 (present participle modifier)", "exp": "Modifies 정책; 강조하다 → 강조하는 describes the nature of the policy.", "example_in_sentence": "강조하는 정책"}]}, {"text": "1950년대는 한국전쟁이 끝난 직후로, 세계가 두 개의 진영으로 나뉘어 있던 시기였어요.", "translation": "The 1950s was a period shortly after the Korean War ended, when the world was divided into two blocs.", "vocab": [{"ko": "직후", "en": "immediately after; right after"}, {"ko": "진영", "en": "camp; bloc; faction"}, {"ko": "나뉘다", "en": "to be divided; to be split"}], "analysis": [{"type": "grammar", "label": "~ㄴ (past participle modifier)", "exp": "Modifies noun; 끝나다 → 끝난 describes a completed action.", "example_in_sentence": "끝난 직후"}, {"type": "grammar", "label": "~어 있던 (past progressive state)", "exp": "Indicates an ongoing state in the past; 나뉘다 → 나뉘어 있던.", "example_in_sentence": "나뉘어 있던 시기"}]}, {"text": "이런 상황에서 소련의 대인도 외교 정책을 엿볼 수 있는 흥미로운 자료입니다.", "translation": "It is an interesting document that offers a glimpse of the Soviet Union''s foreign policy toward India in this situation.", "vocab": [{"ko": "상황", "en": "situation; circumstance"}, {"ko": "엿보다", "en": "to glimpse; to peek; to get a sense of"}, {"ko": "흥미롭다", "en": "to be interesting; to be fascinating"}], "analysis": [{"type": "grammar", "label": "~ㄹ 수 있는 (ability/possibility modifier)", "exp": "Expresses possibility; verb + ㄹ 수 있다 → ㄹ 수 있는 (modifier form).", "example_in_sentence": "엿볼 수 있는 흥미로운 자료"}]}, {"text": "이 포스터는 현재 해외 온라인 커뮤니티에서 많은 관심을 받고 있어요.", "translation": "This poster is currently receiving much attention in overseas online communities.", "vocab": [{"ko": "현재", "en": "currently; now; present"}, {"ko": "관심을 받다", "en": "to receive attention; to be of interest"}], "analysis": [{"type": "grammar", "label": "~고 있어요 (progressive aspect)", "exp": "Indicates ongoing action; 받다 → 받고 있어요 emphasizes continuous reception of attention.", "example_in_sentence": "관심을 받고 있어요"}, {"type": "expression", "label": "관심을 받다 (receive attention)", "exp": "Collocation: object + 을/를 받다 pattern; literally ''to receive interest/attention.''", "example_in_sentence": "많은 관심을 받고 있어요"}]}, {"text": "냉전 시대의 국제 관계와 선전 문화를 이해하는 데 도움이 되는 귀중한 역사적 증거로 평가받고 있습니다.", "translation": "It is being evaluated as valuable historical evidence that helps in understanding international relations and propaganda culture of the Cold War era.", "vocab": [{"ko": "이해하다", "en": "to understand; to comprehend"}, {"ko": "도움이 되다", "en": "to be helpful; to help"}, {"ko": "귀중하다", "en": "to be precious; to be valuable"}, {"ko": "증거", "en": "evidence; proof"}], "analysis": [{"type": "grammar", "label": "~는 데 도움이 되다", "exp": "Means ''to help in doing ~''. 이해하다 → 이해하는 데 도움이 되다 = to help in understanding.", "example_in_sentence": "이해하는 데 도움이 되는"}, {"type": "grammar", "label": "~고 있습니다 (progressive aspect, formal)", "exp": "Present progressive in formal register; 평가받다 → 평가받고 있습니다.", "example_in_sentence": "평가받고 있습니다"}]}], "version": "s6"}', vocab = '[{"ko": "만들어지다", "en": "to be made; to be created", "note": ""}, {"ko": "선전", "en": "propaganda; promotion", "note": ""}, {"ko": "화제가 되다", "en": "to become a topic; to attract attention", "note": ""}, {"ko": "담기다", "en": "to be contained; to be embedded", "note": ""}, {"ko": "메시지", "en": "message", "note": ""}, {"ko": "냉전", "en": "Cold War", "note": ""}, {"ko": "맺다", "en": "to form; to establish", "note": ""}, {"ko": "자료", "en": "material; data; resource", "note": ""}, {"ko": "당시", "en": "at that time; then", "note": ""}, {"ko": "우호", "en": "friendship; friendliness", "note": ""}, {"ko": "강조하다", "en": "to emphasize; to stress", "note": ""}, {"ko": "펼치다", "en": "to unfold; to carry out; to pursue", "note": ""}, {"ko": "직후", "en": "immediately after; right after", "note": ""}, {"ko": "진영", "en": "camp; bloc; faction", "note": ""}, {"ko": "나뉘다", "en": "to be divided; to be split", "note": ""}, {"ko": "상황", "en": "situation; circumstance", "note": ""}, {"ko": "엿보다", "en": "to glimpse; to peek; to get a sense of", "note": ""}, {"ko": "흥미롭다", "en": "to be interesting; to be fascinating", "note": ""}, {"ko": "현재", "en": "currently; now; present", "note": ""}, {"ko": "관심을 받다", "en": "to receive attention; to be of interest", "note": ""}, {"ko": "이해하다", "en": "to understand; to comprehend", "note": ""}, {"ko": "도움이 되다", "en": "to be helpful; to help", "note": ""}, {"ko": "귀중하다", "en": "to be precious; to be valuable", "note": ""}, {"ko": "증거", "en": "evidence; proof", "note": ""}, {"word": "포스터", "reading": "poseuteo", "meaning": "poster", "context": "1950년대에 만들어진 소련-인도 우정 선전 포스터"}, {"word": "외교", "reading": "oegyyo", "meaning": "diplomacy; diplomatic relations", "context": "소련의 대인도 외교 정책을 엿볼 수"}, {"word": "커뮤니티", "reading": "keomyuniti", "meaning": "community", "context": "해외 온라인 커뮤니티에서 많은 관심을"}, {"word": "역사적", "reading": "yeoksajok", "meaning": "historical", "context": "냉전 시대의 국제 관계와 선전 문화를"}]', grammar = '{"patterns": [{"name": "~(으)ㄴ (past modifier)", "level": "Intermediate", "exp": "Past modifier on a passive verb. 만들어지다 → 만들어진 포스터 = a poster that was made.", "ex_ko": "1950년대에 만들어진 소련-인도 우정 선전 포스터가 온라인에서 화제가 되고 있어요.", "ex_en": "A Soviet-Indian friendship propaganda poster created in the 1950s is becoming a topic of discussion online."}, {"name": "~고 있어요 (progressive aspect)", "level": "Intermediate", "exp": "Indicates an ongoing action in present tense; ~고 있다 in polite form emphasizes continuity.", "ex_ko": "1950년대에 만들어진 소련-인도 우정 선전 포스터가 온라인에서 화제가 되고 있어요.", "ex_en": "A Soviet-Indian friendship propaganda poster created in the 1950s is becoming a topic of discussion online."}, {"name": "~(이)라는 (quoting modifier)", "level": "Intermediate", "exp": "Quotes content to describe the noun after it. ''...형제다''라는 메시지 = a message saying ''...are brothers''.", "ex_ko": "포스터에는 ''소련인과 인도인은 형제다''라는 메시지가 담겨 있습니다.", "ex_en": "The poster contains a message saying ''Soviets and Indians are brothers.''"}, {"name": "~어 있다 (resultative state)", "level": "Intermediate", "exp": "Indicates a state resulting from a completed action; 담기다 → 담겨 있다.", "ex_ko": "포스터에는 ''소련인과 인도인은 형제다''라는 메시지가 담겨 있습니다.", "ex_en": "The poster contains a message saying ''Soviets and Indians are brothers.''"}, {"name": "~었던 (past tense participle with experiential nuance)", "level": "Intermediate", "exp": "Modifies noun to indicate past completed action; 맺다 → 맺었던. Often used to reference historical or past experience.", "ex_ko": "이 포스터는 냉전 시대에 소련과 인도가 맺었던 특별한 관계를 보여주는 역사적 자료예요.", "ex_en": "This poster is a historical material that shows the special relationship that the Soviet Union and India formed during the Cold War era."}, {"name": "~는 (present participle modifier)", "level": "Intermediate", "exp": "Modifies noun; 보여주다 → 보여주는 indicates an action defining the noun.", "ex_ko": "이 포스터는 냉전 시대에 소련과 인도가 맺었던 특별한 관계를 보여주는 역사적 자료예요.", "ex_en": "This poster is a historical material that shows the special relationship that the Soviet Union and India formed during the Cold War era."}, {"name": "~ㄴ (past participle modifier)", "level": "Intermediate", "exp": "Modifies noun; 끝나다 → 끝난 describes a completed action.", "ex_ko": "1950년대는 한국전쟁이 끝난 직후로, 세계가 두 개의 진영으로 나뉘어 있던 시기였어요.", "ex_en": "The 1950s was a period shortly after the Korean War ended, when the world was divided into two blocs."}, {"name": "~어 있던 (past progressive state)", "level": "Intermediate", "exp": "Indicates an ongoing state in the past; 나뉘다 → 나뉘어 있던.", "ex_ko": "1950년대는 한국전쟁이 끝난 직후로, 세계가 두 개의 진영으로 나뉘어 있던 시기였어요.", "ex_en": "The 1950s was a period shortly after the Korean War ended, when the world was divided into two blocs."}, {"name": "~ㄹ 수 있는 (ability/possibility modifier)", "level": "Intermediate", "exp": "Expresses possibility; verb + ㄹ 수 있다 → ㄹ 수 있는 (modifier form).", "ex_ko": "이런 상황에서 소련의 대인도 외교 정책을 엿볼 수 있는 흥미로운 자료입니다.", "ex_en": "It is an interesting document that offers a glimpse of the Soviet Union''s foreign policy toward India in this situation."}, {"name": "~는 데 도움이 되다", "level": "Intermediate", "exp": "Means ''to help in doing ~''. 이해하다 → 이해하는 데 도움이 되다 = to help in understanding.", "ex_ko": "냉전 시대의 국제 관계와 선전 문화를 이해하는 데 도움이 되는 귀중한 역사적 증거로 평가받고 있습니다.", "ex_en": "It is being evaluated as valuable historical evidence that helps in understanding international relations and propaganda culture of the Cold War era."}, {"name": "~고 있습니다 (progressive aspect, formal)", "level": "Intermediate", "exp": "Present progressive in formal register; 평가받다 → 평가받고 있습니다.", "ex_ko": "냉전 시대의 국제 관계와 선전 문화를 이해하는 데 도움이 되는 귀중한 역사적 증거로 평가받고 있습니다.", "ex_en": "It is being evaluated as valuable historical evidence that helps in understanding international relations and propaganda culture of the Cold War era."}]}', updated_at = now() where article_id = 'moqefh6bm6iv' and md5(translation) = '893f04636ff449074c1bcbd5d36fd178';
update public.article_cache set translation = '{"texts": ["Photos of the moon taken from NASA''s spacecraft Artemis II are generating buzz. The view of the moon through the spacecraft''s window is incredibly beautiful.", "The Artemis program is a project to send humans back to the moon. Korea is also becoming increasingly interested in space development.", "This photo has attracted a lot of attention on the internet. The view of the moon from space is truly amazing. We will be able to see many more space photos in the future."], "sentences": [{"text": "미국의 우주선 아르테미스 2호(Artemis II)에서 찍은 달 사진이 화제예요.", "translation": "A photo of the moon taken from the US spacecraft Artemis II is becoming a hot topic.", "vocab": [{"ko": "우주선", "en": "spacecraft", "note": "우주(space) + 선(ship/vessel)"}, {"ko": "화제", "en": "hot topic, subject of discussion", "note": "Often used with 이다 or ~예요"}, {"ko": "찍다", "en": "to take (a photo)", "note": "Past participle form: 찍은"}], "grammar": [{"pattern": "~ㄴ (descriptive past modifier)", "exp": "Modifies a noun with a past or completed action without indicating tense.", "example_in_sentence": "찍은 달 사진 (photo taken of the moon)"}, {"pattern": "~예요 (copula, informal polite)", "exp": "Connects a noun or noun phrase as the predicate in informal polite speech.", "example_in_sentence": "화제예요 (is a hot topic)"}], "analysis": []}, {"text": "우주선 창문을 통해 본 달의 모습이 매우 아름다워요.", "translation": "The appearance of the moon seen through the spacecraft window is very beautiful.", "vocab": [{"ko": "창문", "en": "window", "note": "Compound: 창(window frame) + 문(door/opening)"}, {"ko": "모습", "en": "appearance, form, sight", "note": "Neutral word for how something looks"}, {"ko": "아름답다", "en": "to be beautiful", "note": "Adjective; becomes 아름다워요 in ~어요 form"}], "grammar": [{"pattern": "~을/를 통해 (by means of, through)", "exp": "Indicates the method or medium by which an action occurs.", "example_in_sentence": "창문을 통해 본 (seen through the window)"}], "analysis": []}, {"text": "아르테미스 계획은 사람을 다시 달에 보내는 프로젝트예요.", "translation": "The Artemis plan is a project to send people to the moon again.", "vocab": [{"ko": "계획", "en": "plan, project", "note": "Noun used in formal contexts"}, {"ko": "보내다", "en": "to send", "note": "Verb; infinitive form needed before ~는 (present modifier)"}], "grammar": [{"pattern": "~는 (present/habitual modifier)", "exp": "Modifies a noun with an ongoing or habitual action.", "example_in_sentence": "사람을 다시 달에 보내는 프로젝트 (project to send people to the moon again)"}], "analysis": []}, {"text": "한국도 우주 개발에 관심이 많아지고 있어요.", "translation": "Korea is also becoming more interested in space development.", "vocab": [{"ko": "우주 개발", "en": "space development", "note": "우주(space) + 개발(development)"}, {"ko": "관심", "en": "interest, attention", "note": "Noun; often used with 많다 or 있다"}], "grammar": [{"pattern": "~어지다 / ~아지다 (become, turn into)", "exp": "Indicates a change of state or a gradual transition.", "example_in_sentence": "관심이 많아지고 있어요 (is becoming more interested)"}, {"pattern": "~고 있다 (progressive aspect)", "exp": "Shows an ongoing or continuous action in progress.", "example_in_sentence": "많아지고 있어요 (is becoming/growing)"}], "analysis": []}, {"text": "이 사진은 인터넷에서 많은 사람들의 관심을 받았어요.", "translation": "This photo received the attention of many people on the internet.", "vocab": [{"ko": "인터넷", "en": "internet", "note": "Loanword from English"}, {"ko": "관심을 받다", "en": "to receive attention/interest", "note": "Fixed expression: 관심(attention) + 을 받다(to receive)"}], "grammar": [{"pattern": "~ㄴ (past modifier)", "exp": "Modifies a noun with a completed action.", "example_in_sentence": "받았어요 (received — past tense)"}], "analysis": []}, {"text": "우주에서 본 달의 모습은 정말 신기해요.", "translation": "The appearance of the moon seen from space is really amazing.", "vocab": [{"ko": "신기하다", "en": "to be amazing, wonderful, strange", "note": "Adjective describing something surprising or unusual"}], "grammar": [{"pattern": "~ㄴ (descriptive past modifier)", "exp": "Modifies a noun with a past or descriptive action.", "example_in_sentence": "본 달의 모습 (appearance of the moon seen)"}], "analysis": []}, {"text": "앞으로 더 많은 우주 사진을 볼 수 있을 거예요.", "translation": "We will be able to see more space photos in the future.", "vocab": [{"ko": "앞으로", "en": "from now on, in the future", "note": "Adverb indicating future time"}], "grammar": [{"pattern": "~을/를 수 있다 (ability, possibility)", "exp": "Indicates capability or the possibility of an action.", "example_in_sentence": "볼 수 있을 거예요 (will be able to see)"}, {"pattern": "~ㄹ/을 거예요 (future conjecture)", "exp": "Expresses a prediction or expectation about a future event.", "example_in_sentence": "볼 수 있을 거예요 (will likely be able to see)"}], "analysis": []}]}', vocab = '[{"ko": "우주선", "en": "spacecraft", "note": "우주(space) + 선(ship/vessel)"}, {"ko": "화제", "en": "hot topic, subject of discussion", "note": "Often used with 이다 or ~예요"}, {"ko": "찍다", "en": "to take (a photo)", "note": "Past participle form: 찍은"}, {"ko": "창문", "en": "window", "note": "Compound: 창(window frame) + 문(door/opening)"}, {"ko": "모습", "en": "appearance, form, sight", "note": "Neutral word for how something looks"}, {"ko": "아름답다", "en": "to be beautiful", "note": "Adjective; becomes 아름다워요 in ~어요 form"}, {"ko": "계획", "en": "plan, project", "note": "Noun used in formal contexts"}, {"ko": "보내다", "en": "to send", "note": "Verb; infinitive form needed before ~는 (present modifier)"}, {"ko": "우주 개발", "en": "space development", "note": "우주(space) + 개발(development)"}, {"ko": "관심", "en": "interest, attention", "note": "Noun; often used with 많다 or 있다"}, {"ko": "인터넷", "en": "internet", "note": "Loanword from English"}, {"ko": "관심을 받다", "en": "to receive attention/interest", "note": "Fixed expression: 관심(attention) + 을 받다(to receive)"}, {"ko": "신기하다", "en": "to be amazing, wonderful, strange", "note": "Adjective describing something surprising or unusual"}, {"ko": "앞으로", "en": "from now on, in the future", "note": "Adverb indicating future time"}]', grammar = '{"patterns": []}', updated_at = now() where article_id = 'moqeg6dntikf' and md5(translation) = 'dae50bd7ddcddb4d6284cfa271bb7c73';
update public.article_cache set translation = '{"texts": ["Russia''s Akula-class submarine is the world''s largest submarine. Its official name is Project 941 Akula-class.", "The size of this submarine is truly remarkable. Its height is the same as a 9-story building. In terms of displacement (the amount of water it displaces), it is the largest submarine in history.", "TK-208 is one of this series. It is powered by nuclear energy and can fire missiles.", "These giant submarines were built during the Cold War era. Even now, many people are amazed by their size. It can be said to be like a giant monster in the sea."], "sentences": [{"text": "러시아의 아쿨라급 잠수함은 세계에서 가장 큰 잠수함입니다.", "translation": "Russia''s Akula-class submarine is the largest submarine in the world.", "vocab": [{"ko": "잠수함", "en": "submarine", "note": "잠 (submerge) + 수 (water) + 함 (ship)"}, {"ko": "아쿨라급", "en": "Akula-class", "note": "급 means ''class'' or ''grade''"}], "grammar": [{"pattern": "~ㄴ/은 N은/는 Adj입니다", "exp": "Standard copula pattern stating a characteristic or classification of the subject", "example_in_sentence": "러시아의 아쿨라급 잠수함은 세계에서 가장 큰 잠수함입니다"}], "analysis": []}, {"text": "정식 이름은 프로젝트 941 아쿨라급이에요.", "translation": "The official name is Project 941 Akula-class.", "vocab": [{"ko": "정식", "en": "official; formal", "note": "Used with 이름, 명칭, etc."}, {"ko": "프로젝트", "en": "project", "note": "Loanword from English"}], "grammar": [{"pattern": "~이에요/에요", "exp": "Informal copula used in spoken Korean; softer than -입니다", "example_in_sentence": "정식 이름은 프로젝트 941 아쿨라급이에요"}], "analysis": []}, {"text": "이 잠수함의 크기는 정말 놀랍습니다.", "translation": "The size of this submarine is truly remarkable.", "vocab": [{"ko": "크기", "en": "size; scale", "note": "크다 (big) + 기 (noun suffix)"}, {"ko": "놀랍다", "en": "surprising; remarkable; astonishing", "note": "Often used to express amazement"}], "grammar": [{"pattern": "~는 + Adj습니다/어요", "exp": "Present tense adjectival predicate describing a state", "example_in_sentence": "이 잠수함의 크기는 정말 놀랍습니다"}], "analysis": []}, {"text": "높이가 9층 건물과 같아요.", "translation": "The height is equivalent to a 9-story building.", "vocab": [{"ko": "높이", "en": "height", "note": "높다 (tall) + 이 (noun suffix)"}, {"ko": "층", "en": "story; floor; layer", "note": "Counter word for building levels"}], "grammar": [{"pattern": "~과/와 같다", "exp": "Means ''to be the same as'' or ''equivalent to''; expresses comparison", "example_in_sentence": "높이가 9층 건물과 같아요"}], "analysis": []}, {"text": "배수량(물을 밀어내는 양)으로는 역사상 가장 큰 잠수함이에요.", "translation": "In terms of displacement (the amount of water it displaces), it is the largest submarine in history.", "vocab": [{"ko": "배수량", "en": "displacement (nautical term)", "note": "배 (ship) + 수 (water) + 량 (amount)"}, {"ko": "역사상", "en": "in history; historically", "note": "역사 (history) + 상 (adverbial suffix)"}], "grammar": [{"pattern": "~(으)로는", "exp": "Marks the aspect or criterion by which something is judged (''in terms of'')", "example_in_sentence": "배수량(물을 밀어내는 양)으로는 역사상 가장 큰 잠수함이에요"}], "analysis": []}, {"text": "TK-208은 이 시리즈 중 하나입니다.", "translation": "TK-208 is one of the submarines in this series.", "vocab": [{"ko": "시리즈", "en": "series", "note": "Loanword from English"}], "grammar": [], "analysis": []}, {"text": "원자력으로 움직이고 미사일을 쏠 수 있어요.", "translation": "It moves with nuclear power and can fire missiles.", "vocab": [{"ko": "원자력", "en": "nuclear power; atomic energy", "note": "원자 (atom) + 력 (power)"}, {"ko": "미사일", "en": "missile", "note": "Loanword from English"}], "grammar": [{"pattern": "~고 V", "exp": "Connects two actions in sequence; ''and'' or ''while also''", "example_in_sentence": "원자력으로 움직이고 미사일을 쏠 수 있어요"}, {"pattern": "V + 을/ㄹ 수 있다", "exp": "Expresses ability or possibility; ''can'' or ''is able to''", "example_in_sentence": "미사일을 쏠 수 있어요"}], "analysis": []}, {"text": "이런 거대한 잠수함은 냉전 시대에 만들어졌습니다.", "translation": "This kind of enormous submarine was built during the Cold War era.", "vocab": [{"ko": "거대하다", "en": "to be gigantic;